    except BillingError as e: print("nonpos:",e.code)

# not captured
p=mk("authorized")
try: outage_refund(p,Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# rounding half-even
p=mk("captured","10.00"); outage_refund(p,Decimal("0.005"),T0); print("rounded:",p.refunded_amount)
